mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM trips
    WHERE id = #{tripId}
      AND is_deleted = 0
)

mapper.update:
UPDATE trip_countries
SET target_budget = #{localTravelTarget}
WHERE id = #{tripCountryId}
  AND is_deleted = 0

UPDATE trips
SET total_target_amount = #{totalTargetAmount}
WHERE id = #{tripId}
  AND is_deleted = 0

mapper.select:
SELECT balance
FROM trip_wallets
WHERE user_id = #{userId}

mapper.update:
UPDATE saving_plans
SET monthly_amount = #{monthlyAmount}
WHERE id = #{id}
  AND is_deleted = 0
